(function($){
'use strict';

/* ── Global Styles: Color swatch preview ────────────────────── */
$(document).on('change', '.eltiz-color-swatch-input', function(){
  var val     = $(this).val();
  var preview = $(this).closest('.eltiz-color-swatch-row').find('.eltiz-color-swatch-row__preview');
  preview.css('background-color', val);
});

/* ── Template import ─────────────────────────────────────────── */
$(document).on('click', '#eltiz-import-template-btn', function(e){
  e.preventDefault();
  $('#eltiz-import-template-file').trigger('click');
});

$('#eltiz-import-template-file').on('change', function(){
  var file = this.files[0];
  if(!file) return;
  if(!file.name.endsWith('.json')){
    alert(eltizAdmin.i18n.invalidJson || 'Please select a valid JSON file.');
    return;
  }
  var fd = new FormData();
  fd.append('action', 'eltiz_import_template');
  fd.append('nonce',  eltizAdmin.nonce);
  fd.append('file',   file);
  $.ajax({
    url:         eltizAdmin.ajaxUrl,
    type:        'POST',
    data:        fd,
    processData: false,
    contentType: false,
    success: function(res){
      if(res.success){
        window.location.reload();
      } else {
        alert(res.data || 'Import failed.');
      }
    }
  });
});

/* ── Template export ─────────────────────────────────────────── */
$(document).on('click', '.eltiz-export-template', function(e){
  e.preventDefault();
  var id  = $(this).data('id');
  var url = eltizAdmin.restUrl + 'eltiz/v1/templates/' + id + '/export?nonce=' + eltizAdmin.nonce;
  window.location.href = url;
});

/* ── Template delete ─────────────────────────────────────────── */
$(document).on('click', '.eltiz-delete-template', function(e){
  e.preventDefault();
  if(!confirm(eltizAdmin.i18n.confirmDelete || 'Delete this template?')) return;
  var id   = $(this).data('id');
  var $row = $(this).closest('.eltiz-template-card, tr');
  $.ajax({
    url:      eltizAdmin.restUrl + 'eltiz/v1/templates/' + id,
    type:     'DELETE',
    beforeSend: function(xhr){ xhr.setRequestHeader('X-WP-Nonce', eltizAdmin.restNonce); },
    success:  function(){ $row.fadeOut(300, function(){ $row.remove(); }); },
    error:    function(){ alert('Delete failed.'); }
  });
});

/* ── Settings: confirm uninstall ─────────────────────────────── */
$(document).on('click', '#eltiz-uninstall-btn', function(e){
  var msg = eltizAdmin.i18n.confirmUninstall || 'This will delete ALL Eltiz Builder data. Are you absolutely sure?';
  if(!confirm(msg)){ e.preventDefault(); }
});

/* ── Module toggles ──────────────────────────────────────────── */
$(document).on('change', '.eltiz-module-toggle', function(){
  var module  = $(this).data('module');
  var enabled = $(this).is(':checked') ? 1 : 0;
  $.post(eltizAdmin.ajaxUrl, {
    action:  'eltiz_toggle_module',
    nonce:   eltizAdmin.nonce,
    module:  module,
    enabled: enabled,
  });
});

/* ── Dismissible notices ─────────────────────────────────────── */
$(document).on('click', '.eltiz-notice-dismiss', function(){
  $(this).closest('.notice').fadeOut(200, function(){ $(this).remove(); });
});

})(jQuery);
